}

export interface DashboardData {
  weather: WeatherData;
  finance: FinanceData;
  stocks: StockInfo[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { DashboardData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function fetchDashboardData(): Promise<DashboardData> {
  const prompt = `
    통영(경상남도 통영시)을 기준으로 오늘 아침 대시보드 데이터를 생성해주세요.
    다음 정보들이 포함되어야 하며, 반드시 JSON 형식으로 반환해야 합니다:
    1. 날씨: 현재 기온, 최고/최저 기온, 습도, 시간대별 바람 정보(방위, 풍속 m/s), 물때 정보(만조/간조 시간 및 조위).
    2. 경제: 어제 종가 기준 S&P 500, 나스닥, 필라델피아 반도체 지수 수치 및 등락폭. 현재 원/달러 환율, 미국 국채 10년물 금리. 주식 및 물류 유통 관련 핵심 뉴스 3개.
    3. 주식: 삼성전자, SK하이닉스, 에코프로비엠, 현대차의 현재가와 전일대비 등락률.

    데이터 구조는 다음과 같아야 합니다:
    {
      "weather": {
        "temperature": string,
        "lowTemp": string,
        "highTemp": string,
        "humidity": string,
        "windForecast": [{"time": string, "direction": string, "speed": number}],
        "tides": [{"time": string, "type": "만조" | "간조", "level": string, "change": string}]
      },
      "finance": {
        "indices": {
          "sp500": string, "sp500Change": string,
          "nasdaq": string, "nasdaqChange": string,
          "philSemi": string, "philSemiChange": string
        },
        "indicators": { "usdKrw": string, "ust10y": string },
        "news": [{"title": string, "summary": string, "link": string}]
      },
      "stocks": [{"name": string, "price": string, "changeRate": string, "isUp": boolean}]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    // Clean JSON if needed (sometimes wrapped in markdown code blocks)
    const cleanedJson = text.replace(/```json|```/g, "").trim();
    return JSON.parse(cleanedJson) as DashboardData;
  } catch (error) {
    console.error("Error fetching dashboard data:", error);
    throw error;
  }
}

