import React from 'react';
import { WeatherData } from '../types';

interface Props {
  data: WeatherData;
}

const WeatherCard: React.FC<Props> = ({ data }) => {
  const maxWind = Math.max(...data.windForecast.map(w => w.speed));
  const isSurfingDay = maxWind >= 6;

  // Parse and sort tide data for the graph
  const tidePoints = data.tides.map(t => {
    const [h, m] = t.time.split(':').map(Number);
    const minutes = h * 60 + m;
    // Extract number from string (e.g., "234" or "234cm")
    const level = parseInt(t.level.replace(/[^0-9]/g, ''), 10) || 0;
    return { ...t, minutes, level };
  }).sort((a, b) => a.minutes - b.minutes);

  const renderTideGraph = () => {
    if (tidePoints.length === 0) return <div className="text-slate-500 text-sm py-4 text-center">물때 정보가 없습니다.</div>;

    const width = 800;
    const height = 220;
    const paddingX = 60;
    const paddingY = 40;

    // Determine scale bounds
    const minTime = Math.min(...tidePoints.map(p => p.minutes)) - 60; // Start 1h before first tide
    const maxTime = Math.max(...tidePoints.map(p => p.minutes)) + 60; // End 1h after last tide
    const minLevel = Math.min(...tidePoints.map(p => p.level));
    const maxLevel = Math.max(...tidePoints.map(p => p.level));
    // Add buffer to Y axis
    const levelRange = maxLevel - minLevel || 100;
    const yBuffer = levelRange * 0.2;
    const yMinBound = minLevel - yBuffer;
    const yMaxBound = maxLevel + yBuffer;

    const getX = (m: number) => paddingX + ((m - minTime) / (maxTime - minTime)) * (width - paddingX * 2);
    // Invert Y because SVG coordinate system starts from top
    const getY = (l: number) => height - paddingY - ((l - yMinBound) / (yMaxBound - yMinBound)) * (height - paddingY * 2);

    const points = tidePoints.map(p => ({
      x: getX(p.minutes),
      y: getY(p.level),
      data: p
    }));

    // Construct Smooth Curved Path (Cubic Bezier)
    // We want horizontal tangents at the peaks and troughs (Manjo/Ganjo)
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p1 = points[i];
      const p2 = points[i + 1];

      // Control points for a sine-like wave between peak and trough
      // Using 50% distance for control points ensures a smooth transition
      const cp1x = p1.x + (p2.x - p1.x) / 2;
      const cp1y = p1.y; // Horizontal tangent from p1
      const cp2x = p2.x - (p2.x - p1.x) / 2;
      const cp2y = p2.y; // Horizontal tangent into p2

      d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
    }

    // Path for the gradient fill (close the loop at the bottom)
    const fillD = `${d} L ${points[points.length - 1].x} ${height} L ${points[0].x} ${height} Z`;

    return (
      <div className="w-full overflow-hidden mt-4 select-none">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-auto drop-shadow-lg">
          <defs>
            <linearGradient id="waterGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#60a5fa" stopOpacity="0.3" />
              <stop offset="100%" stopColor="#60a5fa" stopOpacity="0.05" />
            </linearGradient>
            <filter id="neonGlow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="2" result="coloredBlur" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {/* Water Fill */}
          <path d={fillD} fill="url(#waterGradient)" />

          {/* Wave Line */}
          <path d={d} fill="none" stroke="#60a5fa" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

          {/* Data Points */}
          {points.map((p, i) => {
            const isHigh = p.data.type === '만조';
            // High tide: Red/Warm, Low tide: Blue/Cool
            const color = isHigh ? '#f87171' : '#38bdf8'; 

            return (
              <g key={i}>
                {/* Dashed Guide Line */}
                <line x1={p.x} y1={p.y} x2={p.x} y2={height - 25} stroke="white" strokeOpacity="0.1" strokeDasharray="4 4" strokeWidth="1" />

                {/* Point Marker */}
                <circle cx={p.x} cy={p.y} r="6" fill="#1e293b" stroke={color} strokeWidth="3" />

                {/* Tide Type Label (High/Low) */}
                <text 
                  x={p.x} 
                  y={p.y - 28} 
                  textAnchor="middle" 
                  fill="white" 
                  fontSize="18" 
                  fontWeight="bold" 
                  className="tracking-wider"
                  style={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}
                >
                  {p.data.type}
                </text>

                {/* Level Value */}
                <text 
                  x={p.x} 
                  y={p.y - 10} 
                  textAnchor="middle" 
                  fill={color} 
                  fontSize="16" 
                  fontWeight="600"
                >
                  {p.data.level}
                </text>

                {/* Time Label (Bottom) */}
                <text 
                  x={p.x} 
                  y={height - 5} 
                  textAnchor="middle" 
                  fill="#94a3b8" 
                  fontSize="18" 
                  fontWeight="500"
                >
                  {p.data.time}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
    );
  };

  return (
