  const prompt = `
    통영(경상남도 통영시)을 기준으로 오늘 아침 대시보드 데이터를 생성해주세요.
    다음 정보들이 포함되어야 하며, 반드시 JSON 형식으로 반환해야 합니다:
    1. 날씨: 현재 기온, 최고/최저 기온, 습도.
       - 바람 정보: 현재 시간부터 향후 8시간 동안의 "1시간 간격" 바람 정보(시간, 방위, 풍속 m/s).
       - 물때 정보: 오늘이 "몇 물"인지(예: 7물, 조금 등)를 나타내는 물때 정보(tideCycle), 그리고 만조/간조 시간 및 조위.
    2. 경제: 어제 종가 기준 S&P 500, 나스닥, 필라델피아 반도체 지수 수치 및 등락폭. 현재 원/달러 환율, 미국 국채 10년물 금리. 주식 및 물류 유통 관련 핵심 뉴스 3개.
    3. 주식: 삼성전자, SK하이닉스, 에코프로비엠, 현대차의 현재가와 전일대비 등락률.

    데이터 구조는 다음과 같아야 합니다:
    {
      "weather": {
        "temperature": string,
        "lowTemp": string,
        "highTemp": string,
        "humidity": string,
        "tideCycle": string,
        "windForecast": [{"time": string, "direction": string, "speed": number}],
        "tides": [{"time": string, "type": "만조" | "간조", "level": string, "change": string}]
      },
      "finance": {
        "indices": {
          "sp500": string, "sp500Change": string,
          "nasdaq": string, "nasdaqChange": string,
          "philSemi": string, "philSemiChange": string
        },
        "indicators": { "usdKrw": string, "ust10y": string },
        "news": [{"title": string, "summary": string, "link": string}]
      },
      "stocks": [{"name": string, "price": string, "changeRate": string, "isUp": boolean}]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    // Clean JSON if needed (sometimes wrapped in markdown code blocks)
    const cleanedJson = text.replace(/```json|```/g, "").trim();
    return JSON.parse(cleanedJson) as DashboardData;
  } catch (error) {
    console.error("Error fetching dashboard data:", error);
    throw error;
  }
}

import React from 'react';
import { WeatherData } from '../types';

interface Props {
  data: WeatherData;
}

const WeatherCard: React.FC<Props> = ({ data }) => {
  const maxWind = Math.max(...data.windForecast.map(w => w.speed));
  const isSurfingDay = maxWind >= 6;

  // Parse and sort tide data for the graph
  const tidePoints = data.tides.map(t => {
    const [h, m] = t.time.split(':').map(Number);
    const minutes = h * 60 + m;
    // Extract number from string (e.g., "234" or "234cm")
    const level = parseInt(t.level.replace(/[^0-9]/g, ''), 10) || 0;
    return { ...t, minutes, level };
  }).sort((a, b) => a.minutes - b.minutes);

  const renderTideGraph = () => {
    if (tidePoints.length === 0) return <div className="text-slate-500 text-sm py-4 text-center">물때 정보가 없습니다.</div>;

    const width = 800;
    const height = 220;
    const paddingX = 60;
    const paddingY = 40;

    // Determine scale bounds
    const minTime = Math.min(...tidePoints.map(p => p.minutes)) - 60; // Start 1h before first tide
    const maxTime = Math.max(...tidePoints.map(p => p.minutes)) + 60; // End 1h after last tide
    const minLevel = Math.min(...tidePoints.map(p => p.level));
    const maxLevel = Math.max(...tidePoints.map(p => p.level));
    // Add buffer to Y axis
    const levelRange = maxLevel - minLevel || 100;
    const yBuffer = levelRange * 0.2;
    const yMinBound = minLevel - yBuffer;
    const yMaxBound = maxLevel + yBuffer;

    const getX = (m: number) => paddingX + ((m - minTime) / (maxTime - minTime)) * (width - paddingX * 2);
    // Invert Y because SVG coordinate system starts from top
    const getY = (l: number) => height - paddingY - ((l - yMinBound) / (yMaxBound - yMinBound)) * (height - paddingY * 2);

    const points = tidePoints.map(p => ({
      x: getX(p.minutes),
      y: getY(p.level),
      data: p
    }));

    // Construct Smooth Curved Path (Cubic Bezier)
    // We want horizontal tangents at the peaks and troughs (Manjo/Ganjo)
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p1 = points[i];
      const p2 = points[i + 1];

      // Control points for a sine-like wave between peak and trough
      // Using 50% distance for control points ensures a smooth transition
      const cp1x = p1.x + (p2.x - p1.x) / 2;
      const cp1y = p1.y; // Horizontal tangent from p1
      const cp2x = p2.x - (p2.x - p1.x) / 2;
      const cp2y = p2.y; // Horizontal tangent into p2

      d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
    }

    // Path for the gradient fill (close the loop at the bottom)
    const fillD = `${d} L ${points[points.length - 1].x} ${height} L ${points[0].x} ${height} Z`;

    return (
      <div className="w-full overflow-hidden mt-4 select-none">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-auto drop-shadow-lg">
          <defs>
            <linearGradient id="waterGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#60a5fa" stopOpacity="0.3" />
              <stop offset="100%" stopColor="#60a5fa" stopOpacity="0.05" />
            </linearGradient>
            <filter id="neonGlow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="2" result="coloredBlur" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {/* Water Fill */}
          <path d={fillD} fill="url(#waterGradient)" />

          {/* Wave Line */}
          <path d={d} fill="none" stroke="#60a5fa" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

          {/* Data Points */}
          {points.map((p, i) => {
            const isHigh = p.data.type === '만조';
            // High tide: Red/Warm, Low tide: Blue/Cool
            const color = isHigh ? '#f87171' : '#38bdf8'; 

            return (
              <g key={i}>
                {/* Dashed Guide Line */}
                <line x1={p.x} y1={p.y} x2={p.x} y2={height - 25} stroke="white" strokeOpacity="0.1" strokeDasharray="4 4" strokeWidth="1" />

                {/* Point Marker */}
                <circle cx={p.x} cy={p.y} r="6" fill="#1e293b" stroke={color} strokeWidth="3" />

                {/* Tide Type Label (High/Low) */}
                <text 
                  x={p.x} 
                  y={p.y - 28} 
                  textAnchor="middle" 
                  fill="white" 
                  fontSize="18" 
                  fontWeight="bold" 
                  className="tracking-wider"
                  style={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}
                >
                  {p.data.type}
                </text>

                {/* Level Value */}
                <text 
                  x={p.x} 
                  y={p.y - 10} 
                  textAnchor="middle" 
                  fill={color} 
                  fontSize="16" 
                  fontWeight="600"
                >
                  {p.data.level}
                </text>

                {/* Time Label (Bottom) */}
                <text 
                  x={p.x} 
                  y={height - 5} 
                  textAnchor="middle" 
                  fill="#94a3b8" 
                  fontSize="18" 
                  fontWeight="500"
                >
                  {p.data.time}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
    );
  };

  return (
    <div className="glass-card rounded-2xl p-6 h-full flex flex-col gap-6">
      <div className="flex justify-between items-start">
        <div>
          <h2 className="text-2xl font-bold flex items-center gap-2">
            <i className="fas fa-water text-blue-400"></i> 통영 해상 리포트
          </h2>
          <p className="text-slate-400 text-sm">도남동 & 죽림 기준</p>
        </div>
        <div className="flex gap-6 text-right">
          <div>
            <div className="text-xs text-slate-400 font-medium mb-1 uppercase tracking-wider">오늘의 물때</div>
            <div className="text-3xl font-bold text-indigo-300">{data.tideCycle}</div>
          </div>
          <div>
            <div className="text-xs text-slate-400 font-medium mb-1 uppercase tracking-wider">현재 기온</div>
            <div className="text-3xl font-bold text-blue-400">{data.temperature}</div>
            <div className="text-sm text-slate-400 mt-1">
              <span className="text-blue-300">↓{data.lowTemp}</span> / <span className="text-red-300">↑{data.highTemp}</span>
            </div>
          </div>
        </div>
      </div>

      {isSurfingDay && (
        <div className="bg-blue-500/20 border border-blue-400/30 rounded-lg p-3 flex items-center gap-3">
          <i className="fas fa-wind text-blue-300 animate-pulse text-xl"></i>
          <span className="text-blue-100 font-semibold italic text-sm">
            "오늘은 윈드서핑하기 완벽한 날입니다! (최대 {maxWind}m/s)"
          </span>
        </div>
      )}

      <div>
        <h3 className="text-sm font-semibold text-slate-400 mb-3 border-b border-white/10 pb-1">시간대별 바람 정보 (1시간 간격)</h3>
        {/* Horizontal Scroll Container */}
        <div className="flex overflow-x-auto pb-4 gap-2 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
          {data.windForecast.map((w, idx) => (
            <div key={idx} className="flex-shrink-0 w-20 bg-white/5 rounded-lg p-2 text-center border border-white/5 hover:bg-white/10 transition-colors">
              <div className="text-xs text-slate-500 mb-1">{w.time}</div>
              <div className="font-bold text-lg text-blue-200">{w.speed}</div>
              <div className="text-[10px] text-slate-400">m/s</div>
              <div className="text-[10px] text-indigo-300 mt-1">{w.direction}</div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 flex flex-col">
        <h3 className="text-sm font-semibold text-slate-400 mb-1 border-b border-white/10 pb-1">조석 그래프 (만조/간조)</h3>
        {renderTideGraph()}
      </div>
    </div>
  );
};

