import React, { useState, useEffect } from 'react';
import { CalendarEvent } from '../types';

const CalendarWidget: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [events, setEvents] = useState<CalendarEvent[]>([]);

  // Modal Input States
  const [newTime, setNewTime] = useState('');
  const [newTitle, setNewTitle] = useState('');

  // Load events from localStorage on mount
  useEffect(() => {
    const savedEvents = localStorage.getItem('tongyeong_dashboard_events');
    if (savedEvents) {
      setEvents(JSON.parse(savedEvents));
    }
  }, []);

  // Save events to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('tongyeong_dashboard_events', JSON.stringify(events));
  }, [events]);

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const days = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay();
    return { days, firstDay, year, month };
  };

  const { days, firstDay, year, month } = getDaysInMonth(currentDate);

  const prevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  const handleDateClick = (day: number) => {
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    setSelectedDate(dateStr);
    setNewTime('');
    setNewTitle('');
  };

  const addEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDate || !newTime || !newTitle) return;

    const newEvent: CalendarEvent = {
      id: Date.now().toString(),
      date: selectedDate,
      time: newTime,
      title: newTitle,
    };

    setEvents([...events, newEvent].sort((a, b) => a.time.localeCompare(b.time)));
    setNewTitle('');
    setNewTime('');
  };

  const deleteEvent = (id: string) => {
    setEvents(events.filter(ev => ev.id !== id));
  };

  const renderDays = () => {
    const daysArray = [];

    // Empty cells for days before the 1st of the month
    for (let i = 0; i < firstDay; i++) {
      daysArray.push(<div key={`empty-${i}`} className="h-24 bg-white/5 opacity-30 rounded-lg"></div>);
    }

    // Days of the month
    for (let d = 1; d <= days; d++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isToday = new Date().toDateString() === new Date(year, month, d).toDateString();
      const dayEvents = events.filter(ev => ev.date === dateStr);
      const hasEvents = dayEvents.length > 0;

      daysArray.push(
        <div 
          key={d} 
          onClick={() => handleDateClick(d)}
          className={`h-24 rounded-lg p-2 cursor-pointer transition-all border border-white/5 relative group hover:bg-white/10 ${isToday ? 'bg-blue-900/40 border-blue-500/50' : 'bg-white/5'}`}
        >
          <div className="flex justify-between items-start">
            <span className={`text-sm font-bold ${isToday ? 'text-blue-300' : 'text-slate-300'}`}>{d}</span>
            {hasEvents && <span className="w-2 h-2 rounded-full bg-emerald-400"></span>}
          </div>
          <div className="mt-1 space-y-1 overflow-hidden">
             {dayEvents.slice(0, 2).map(ev => (
               <div key={ev.id} className="text-[10px] text-slate-400 truncate bg-black/20 px-1 rounded">
                 {ev.title}
               </div>
             ))}
             {dayEvents.length > 2 && (
               <div className="text-[9px] text-slate-500 text-center">+더보기</div>
             )}
          </div>
        </div>
      );
    }
    return daysArray;
  };

  // Filter events for the selected date modal
  const selectedEvents = selectedDate ? events.filter(ev => ev.date === selectedDate) : [];

  return (
    <div className="glass-card rounded-2xl p-6 relative">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold flex items-center gap-2">
          <i className="fas fa-calendar-alt text-orange-400"></i> 월간 일정
        </h2>
        <div className="flex items-center gap-4">
          <button onClick={prevMonth} className="p-2 hover:bg-white/10 rounded-full transition-colors"><i className="fas fa-chevron-left"></i></button>
          <span className="text-lg font-bold w-24 text-center">{year}. {month + 1}</span>
          <button onClick={nextMonth} className="p-2 hover:bg-white/10 rounded-full transition-colors"><i className="fas fa-chevron-right"></i></button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-2 mb-2 text-center text-slate-400 text-xs font-semibold uppercase">
        <div className="text-red-400">Sun</div>
        <div>Mon</div>
        <div>Tue</div>
        <div>Wed</div>
        <div>Thu</div>
        <div>Fri</div>
        <div className="text-blue-400">Sat</div>
      </div>
      <div className="grid grid-cols-7 gap-2">
        {renderDays()}
      </div>

      {/* Modal / Popup for Adding Events */}
      {selectedDate && (
        <div className="absolute inset-0 bg-slate-900/95 backdrop-blur-sm rounded-2xl p-6 z-20 flex flex-col animate-fade-in">
          <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
            <div>
              <h3 className="text-2xl font-bold text-white">{selectedDate}</h3>
              <p className="text-sm text-slate-400">일정 관리</p>
            </div>
            <button 
              onClick={() => setSelectedDate(null)}
              className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center hover:bg-white/20"
            >
              <i className="fas fa-times"></i>
            </button>
          </div>

          <div className="flex-1 overflow-y-auto mb-4 space-y-2 pr-2 custom-scrollbar">
            {selectedEvents.length === 0 ? (
              <div className="text-center text-slate-500 py-10">등록된 일정이 없습니다.</div>
            ) : (
              selectedEvents.map(ev => (
                <div key={ev.id} className="flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5 group">
                  <div className="bg-indigo-500/20 text-indigo-300 px-2 py-1 rounded text-xs font-bold">
                    {ev.time}
                  </div>
                  <div className="flex-1 font-medium text-slate-200">{ev.title}</div>
                  <button 
                    onClick={() => deleteEvent(ev.id)}
                    className="opacity-0 group-hover:opacity-100 text-slate-500 hover:text-red-400 transition-all px-2"
                  >
                    <i className="fas fa-trash"></i>
                  </button>
                </div>
              ))
            )}
          </div>

          <form onSubmit={addEvent} className="bg-white/5 p-4 rounded-xl border border-white/10">
            <div className="flex gap-2 mb-3">
              <input 
                type="time" 
                value={newTime}
                onChange={(e) => setNewTime(e.target.value)}
                className="bg-slate-800 border border-slate-600 text-white rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500"
                required
              />
              <input 
                type="text" 
                placeholder="일정 내용 입력..." 
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                className="flex-1 bg-slate-800 border border-slate-600 text-white rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-blue-500"
                required
              />
            </div>
            <button 
              type="submit" 
              className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-2 rounded-lg transition-colors flex items-center justify-center gap-2"
            >
              <i className="fas fa-plus"></i> 일정 추가
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

