import React, { useState, useEffect } from 'react';
import { DashboardData } from './types';
import { fetchDashboardData } from './services/geminiService';
import WeatherCard from './components/WeatherCard';
import FinanceCard from './components/FinanceCard';
import StockWatchlist from './components/StockWatchlist';
import ActionButtons from './components/ActionButtons';
import CalendarWidget from './components/CalendarWidget';

const App: React.FC = () => {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    async function init() {
      try {
        setLoading(true);
        const dashboardData = await fetchDashboardData();
        setData(dashboardData);
      } catch (err) {
        setError("데이터를 불러오는 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.");
      } finally {
        setLoading(false);
      }
    }
    init();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-4 bg-[#0f172a]">
        <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-xl font-medium text-slate-300 animate-pulse">
          통영의 아침을 불러오고 있습니다...
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#0f172a] p-4 text-center">
        <div className="text-red-400 text-5xl mb-4"><i className="fas fa-exclamation-triangle"></i></div>
        <div className="text-xl text-slate-300 max-w-md">{error}</div>
        <button 
          onClick={() => window.location.reload()}
          className="mt-6 bg-blue-600 px-6 py-2 rounded-lg font-bold hover:bg-blue-500"
        >
          다시 시도
        </button>
      </div>
    );
  }

  const formattedDate = currentTime.toLocaleDateString('ko-KR', {
    month: 'long',
    day: 'numeric',
    weekday: 'long'
  });

  return (
    <div className="min-h-screen pb-12 overflow-x-hidden">
      {/* Background Decor */}
      <div className="fixed top-0 left-0 w-full h-full pointer-events-none opacity-20 z-0">
        <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-blue-600 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-[400px] h-[400px] bg-emerald-600 rounded-full blur-[100px]"></div>
      </div>

      <header className="relative z-10 px-6 pt-8 pb-4 max-w-7xl mx-auto flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <span className="bg-blue-500 text-white text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-tighter">Dongmyeong Krill</span>
            <span className="text-slate-500 text-sm font-medium">{formattedDate}</span>
          </div>
          <h1 className="text-4xl font-black tracking-tight text-white flex items-center gap-3">
            좋은 아침입니다, 대표님 <span className="animate-bounce">⚓</span>
          </h1>
        </div>
        <div className="text-slate-400 font-medium text-lg flex items-center gap-2">
          <i className="far fa-clock"></i>
          {currentTime.toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' })}
        </div>
      </header>

      <main className="relative z-10 max-w-7xl mx-auto px-6 grid grid-cols-1 gap-6">
        {/* Top Section: Weather & Finance */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">
          <WeatherCard data={data.weather} />
          <FinanceCard data={data.finance} />
        </div>

        {/* Middle Section: Stock Watchlist */}
        <div className="animate-fade-in" style={{ animationDelay: '0.1s' }}>
          <StockWatchlist stocks={data.stocks} />
        </div>

        {/* Bottom Section: Calendar & Actions */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fade-in" style={{ animationDelay: '0.2s' }}>
          <div className="lg:col-span-2">
            <CalendarWidget />
          </div>
          <div className="lg:col-span-1 h-full">
            <ActionButtons />
          </div>
        </div>
      </main>

      <footer className="relative z-10 max-w-7xl mx-auto px-6 mt-12 text-center text-slate-500 text-xs">
        © 2024 동명크릴 통영 비즈니스 비서 서비스 · Powered by Gemini Flash
      </footer>
    </div>
  );
};

export default App;
